-- ************************************** "INFOMART"."V_CUSTOMER_LTV_INSIGHT"
CREATE VIEW IF NOT EXISTS "INFOMART"."V_CUSTOMER_LTV_INSIGHT"
(
  "CUSTOMER_SEGMENT_CD",
  "REGION_NAME",
  "AVERAGE_LTV",
  "TOTAL_REVENUE",
  "TOTAL_COST"
)
AS
SELECT 
    C.CUSTOMER_SEGMENT_CD,
    G.REGION_NAME,
    AVG(FCLTV.LIFETIME_VALUE_AMT) AS AVERAGE_LTV,
    SUM(FCLTV.TOTAL_REVENUE_AMT) AS TOTAL_REVENUE,
    SUM(FCLTV.TOTAL_COST_AMT) AS TOTAL_COST
FROM 
    FACT_CLTV FCLTV
JOIN 
    DIM_CUSTOMER C ON FCLTV.CUSTOMER_HKEY = C.CUSTOMER_HKEY
JOIN 
    DIM_GEOGRAPHY G ON FCLTV.GEOGRAPHY_HKEY = G.GEOGRAPHY_HKEY
GROUP BY 
    C.CUSTOMER_SEGMENT_CD,
    G.REGION_NAME;

